# Option A: Pure Python - Greedy Hill-Climbing vs Quality-Diversity (MAP-Elites) Archive
# Each scaffold has (val_score, cost_bucket) where stepping stones have slightly lower score first!
import random

# Simulated fitness landscape: two niches (fast_simple=0, deep_search=1)
# Niche 0 caps at 0.78; Niche 1 starts lower (0.65) but reaches 0.94 after mutation!
def simulate_evolution(mode, steps=10, seed=7):
    rng = random.Random(seed)
    if mode == "greedy":
        cur_niche, cur_score = 0, 0.72
        best_curve = [cur_score]
        for _ in range(steps):
            # Greedy only accepts immediate improvements -> stays stuck in niche 0!
            cand_niche = 0 if rng.random() < 0.7 else 1
            if cand_niche == 0:
                cand_score = min(0.78, cur_score + rng.uniform(-0.02, 0.025))
            else:
                cand_score = 0.65 + rng.uniform(0.0, 0.05)  # initial dip rejected by greedy!
            if cand_score > cur_score:
                cur_niche, cur_score = cand_niche, cand_score
            best_curve.append(round(cur_score, 4))
        return best_curve
    else:
        # Quality-Diversity Archive keeps best solution PER niche (stepping stones survive!)
        archive = {0: 0.72, 1: 0.65}
        best_curve = [max(archive.values())]
        for _ in range(steps):
            parent_niche = rng.choice([0, 1])
            base = archive[parent_niche]
            if parent_niche == 0:
                cand = min(0.78, base + rng.uniform(-0.01, 0.025))
            else:
                cand = min(0.95, base + rng.uniform(0.01, 0.065))
            if cand > archive[parent_niche]:
                archive[parent_niche] = cand
            best_curve.append(round(max(archive.values()), 4))
        return best_curve

greedy_hist = simulate_evolution("greedy", steps=8)
qd_hist     = simulate_evolution("qd", steps=8)

print("Greedy Hill-Climb best:", greedy_hist)
print("QD Archive (MAP-Elites):", qd_hist)
